import EVPCore
import Foundation

struct Failure: Error, CustomStringConvertible { let description: String }

enum Fixtures {
    /// Generated by Tools/make-fixtures (run through ./test).
    static func url(_ name: String) throws -> URL {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent(".fixtures/\(name)")
        guard FileManager.default.fileExists(atPath: url.path) else { throw Failure(description: "\(name) missing: run ./test, which generates fixtures") }
        return url
    }
}

/// A headless player with every event recorded, for tests that wait on real engine behaviour.
final class Session {
    /// Measured: about 2 s from `loadfile` to 1 s of playback on this machine (see results/*/xunit.xml).
    static let timeout = 5.0

    let player: MpvPlayer
    private(set) var events: [MpvPlayer.Event] = []

    init(loading name: String? = nil) throws {
        player = try MpvPlayer()
        player.onEvent = { [weak self] in self?.events.append($0) }
        if let name {
            try player.load(try Fixtures.url(name))
            try waitFor(.fileLoaded)
        }
    }

    /// Spins the main run loop (where mpv delivers events) until `condition` holds.
    func until(_ what: String, _ condition: () -> Bool) throws {
        let deadline = Date().addingTimeInterval(Self.timeout)
        while !condition() {
            guard Date() < deadline else { throw Failure(description: "timed out after \(Self.timeout) s: \(what)") }
            RunLoop.main.run(mode: .default, before: Date().addingTimeInterval(0.01))
        }
    }

    /// Waits for `event` to arrive after the first `mark` events.
    func waitFor(_ event: MpvPlayer.Event, after mark: Int = 0) throws {
        try until("\(event)") { events[mark...].contains(event) }
    }

    func position() throws -> Double { Double(try player.property("time-pos") ?? "") ?? .nan }

    func waitForPosition(near target: Double, within tolerance: Double) throws {
        try until("position near \(target)") { ((try? position()) ?? .nan).distance(to: target).magnitude <= tolerance }
    }
}
